1: /*
2: 	compat: Some compatibility functions (basic memory & string stuff in separate file)
3: 
4: 	The mpg123 code is determined to keep it's legacy. A legacy of old, old UNIX.
5: 	So anything possibly somewhat advanced should be considered to be put here, with proper #ifdef;-)
6: 
7: 	copyright 2007-2023 by the mpg123 project - free software under the terms of the LGPL 2.1
8: 	see COPYING and AUTHORS files in distribution or http://mpg123.org
9: 	initially written by Thomas Orgis, Windows Unicode stuff by JonY.
10: */
11: 
12: #include "config.h"
13: /* This source file does need _POSIX_SOURCE to get some sigaction. */
14: #define _POSIX_SOURCE
15: #include "compat.h"
16: 
17: #ifdef _MSC_VER
18: #include <io.h>
19: 
20: #if(defined(WINAPI_FAMILY) && (WINAPI_FAMILY==WINAPI_FAMILY_APP))
21: #define WINDOWS_UWP
22: #endif
23: 
24: #endif
25: #ifdef HAVE_SYS_STAT_H
26: #  include <sys/stat.h>
27: #endif
28: #ifdef HAVE_DIRENT_H
29: #  include <dirent.h>
30: #endif
31: 
32: /* Win32 is only supported with unicode now. These headers also cover
33:    module stuff. The WANT_WIN32_UNICODE macro is synonymous with
34:    "want windows-specific API, and only the unicode variants of which". */
35: #ifdef WANT_WIN32_UNICODE
36: #include <wchar.h>
37: #include <windows.h>
38: #include <winnls.h>
39: #include <shlwapi.h>
40: #endif
41: 
42: #include "../common/debug.h"
43: 
44: #ifndef WINDOWS_UWP
45: 
46: char *INT123_compat_getenv(const char* name)
47: {
48: 	char *ret = NULL;
49: #ifdef WANT_WIN32_UNICODE
50: 	wchar_t *env;
51: 	wchar_t *wname = NULL;
52: 	if(INT123_win32_utf8_wide(name, &wname, NULL) > 0)
53: 	{
54: 		env = _wgetenv(wname);
55: 		free(wname);
56: 		if(env)
57: 			INT123_win32_wide_utf8(env, &ret, NULL);
58: 	}
59: #else
60: 	ret = getenv(name);
61: 	if(ret)
62: 		ret = INT123_compat_strdup(ret);
63: #endif
64: 	return ret;
65: }
66: 
67: #endif
68: 
69: #include "wpathconv.h"
70: 
71: /* Always add a default permission mask in case of flags|O_CREAT. */
72: int INT123_compat_open(const char *filename, int flags)
73: {
74: 	int ret;
75: #if defined (WANT_WIN32_UNICODE)
76: 	wchar_t *frag = NULL;
77: 
78: 	frag = u2wlongpath(filename);
79: 	/* Fallback to plain open when ucs-2 conversion fails */
80: 	if(!frag)
81: 		goto open_fallback;
82: 
83: 	/*Try _wopen */
84: 	ret = _wopen(frag, flags|_O_BINARY, _S_IREAD | _S_IWRITE);
85: 	if(ret != -1 )
86: 		goto open_ok; /* msdn says -1 means failure */
87: 
88: open_fallback:
89: #endif
90: 
91: #if defined(MPG123_COMPAT_MSVCRT_IO)
92: 	/* MSDN says POSIX function is deprecated beginning in Visual C++ 2005 */
93: 	/* Try plain old _open(), if it fails, do nothing */
94: 	ret = _open(filename, flags|_O_BINARY, _S_IREAD | _S_IWRITE);
95: #else
96: 	ret = open(filename, flags, S_IRUSR|S_IWUSR|S_IRGRP|S_IWGRP|S_IROTH|S_IWOTH);
97: #endif
98: 
99: #if defined (WANT_WIN32_UNICODE)
100: open_ok:
101: 	free(frag);
102: #endif
103: 
104: 	return ret;
105: }
106: 
107: /* Moved over from wav.c, logic with fallbacks added from the
108:    example of INT123_compat_open(). */
109: FILE* INT123_compat_fopen(const char *filename, const char *mode)
110: {
111: 	FILE* stream = NULL;
112: #ifdef WANT_WIN32_UNICODE
113: 	int cnt = 0;
114: 	wchar_t *wname = NULL;
115: 	wchar_t *wmode = NULL;
116: 
117: 	wname = u2wlongpath(filename);
118: 	if(!wname)
119: 		goto fopen_fallback;
120: 	cnt = INT123_win32_utf8_wide(mode, &wmode, NULL);
121: 	if( (wmode == NULL) || (cnt == 0))
122: 		goto fopen_fallback;
123: 
124: 	stream = _wfopen(wname, wmode);
125: 	if(stream) goto fopen_ok;
126: 
127: fopen_fallback:
128: #endif
129: 	stream = fopen(filename, mode);
130: #ifdef WANT_WIN32_UNICODE
131: 
132: fopen_ok:
133: 	free(wmode);
134: 	free(wname);
135: #endif
136: 	return stream;
137: }
138: 
139: FILE* INT123_compat_fdopen(int fd, const char *mode)
140: {
141: #if defined(MPG123_COMPAT_MSVCRT_IO)
142: 	return _fdopen(fd, mode);
143: #else
144: 	return fdopen(fd, mode);
145: #endif
146: }
147: 
148: int INT123_compat_close(int infd)
149: {
150: #if defined(MPG123_COMPAT_MSVCRT_IO)
151: 	return _close(infd);
152: #else
153: 	return close(infd);
154: #endif
155: }
156: 
157: int INT123_compat_fclose(FILE *stream)
158: {
159: 	return fclose(stream);
160: }
161: 
162: void INT123_compat_binmode(int fd, int enable)
163: {
164: #if   defined(HAVE__SETMODE)
165: 	_setmode(fd, enable ? _O_BINARY : _O_TEXT);
166: #elif defined(HAVE_SETMODE)
167: 	setmode(fd, enable ? O_BINARY : O_TEXT);
168: #endif
169: }
170: 
171: #ifndef WINDOWS_UWP
172: 
173: /*
174: 	The Windows file and path stuff is an extract of jon_y's win32 loader
175: 	prototype from the loader_rework branch. It's been divided in to
176: 	reusable functons by ThOr in the hope to work out some generic-looking
177: 	loader code for both POSIX and Windows. The routines might be
178: 	helpful for consistent path work in other parts of mpg123, too.
179: 
180: 	This all is about getting some working code on a wide range of
181: 	systems while staying somewhat sane. If it does ridiculously inefficient
182: 	things with extraneous copies and grabbing of functions that made
183: 	it late to some official APIs, that's still fine with us.
184: */
185: 
186: #ifdef WANT_WIN32_UNICODE
187: typedef HRESULT (__stdcall *PCA_ptr)( const wchar_t *, const wchar_t*, unsigned long, wchar_t **);
188: #endif
189: 
190: char* INT123_compat_catpath(const char *prefix, const char* path)
191: {
192: 	char *ret = NULL;
193: #ifdef WANT_WIN32_UNICODE
194: 	wchar_t *wprefix = NULL; /* Wide windows versions of */
195: 	wchar_t *wpath   = NULL; /* input arguments. */
196: 	wchar_t *locwret = NULL; /* Tmp return value from LocalAlloc */
197: 	/*
198: 		This variation of combinepath can work with long and UNC paths, but
199: 		is not officially exposed in any DLLs, It also allocates all its buffers
200: 		internally via LocalAlloc, avoiding buffer overflow problems.
201: 		ThOr: I presume this hack is for supporting pre-8 Windows, as
202: 		from Windows 8 on, this is documented in the API.
203: 	*/
204: 	PCA_ptr mypac = NULL;
205: 	HMODULE pathcch = NULL;
206: 
207: 	if(!prefix && !path)
208: 		goto catpath_end;
209: 	wprefix = u2wpath(prefix);
210: 	wpath   = u2wpath(path);
211: 	if((prefix && !wprefix) || (path && !wpath))
212: 		goto catpath_end;
213: 
214: 	/* Again: I presume this whole fun is to get at PathAllocCombine
215: 	   even when pathcch.h is not available (like in MinGW32). */
216: 	if( (pathcch = GetModuleHandleA("kernelbase")) )
217: 		mypac = (PCA_ptr) GetProcAddress(pathcch, "PathAllocCombine");
218: 	if(mypac) /* PATHCCH_ALLOW_LONG_PATH = 1 per API docs */
219: 	{
220: 		debug("Actually calling PathAllocCombine!");
221: 		mypac(wprefix, wpath, 1, &locwret);
222: 	}
223: 	else
224: 	{
225: 		/* Playing safe, if we'd care much about performance, this would be on
226: 		   the stack. */
227: 		locwret = LocalAlloc(LPTR, sizeof(wchar_t)*MAX_PATH);
228: 		if(locwret)
229: 			PathCombineW(locwret, wprefix, wpath);
230: 	}
231: 	ret = w2upath(locwret);
232: 
233: catpath_end:
