430: // Revisit logic of write():
431: // Return -1 if interrupted before any data was written,
432: // set errno to EINTR. Any other error value is serious
433: // for blocking I/O, which we assume here. EAGAIN should be
434: // handed through.
435: // Reaction to zero-sized write attempts could also be funky, so avoid that.
436: // May return short count for various reasons. I assume that
437: // any serious condition will show itself as return value -1
438: // eventually.
439: 
440: // These uninterruptible write/read functions shall persist as long as
441: // possible to finish the desired operation. A short byte count is short
442: // because of a serious reason (maybe EOF, maybe out of disk space). You
443: // can inspect errno.
444: 
445: size_t INT123_unintr_write(int fd, void const *buffer, size_t bytes)
446: {
447: 	size_t written = 0;
448: 	errno = 0;
449: 	while(bytes)
450: 	{
451: 		errno = 0;
452: 		ptrdiff_t part = write(fd, (char*)buffer+written, bytes);
453: 		// Just on short writes, we do not abort. Only when
454: 		// there was no successful operation (even zero write) at all.
455: 		// Any other error than EINTR ends things here.
456: 		if(part >= 0)
457: 		{
458: 			bytes   -= part;
459: 			written += part;
460: 		} else if(errno != EINTR && errno != EAGAIN
461: #if defined(EWOULDBLOCK) && (EWOULDBLOCK != EAGAIN)
462: 			// Not all platforms define it (or only in more modern POSIX modes).
463: 			// Standard says it is supposed to be a macro, so simple check here.
464: 			&& errno != EWOULDBLOCK
465: #endif
466: 		)
467: 			break;
468: 	}
469: 	return written;
470: }
471: 
472: /* Same for reading the data. */
473: size_t INT123_unintr_read(int fd, void *buffer, size_t bytes)
474: {
475: 	size_t got = 0;
476: 	errno = 0;
477: 	while(bytes)
478: 	{
479: 		errno = 0;
480: 		ptrdiff_t part = read(fd, (char*)buffer+got, bytes);
481: 		if(part > 0) // == 0 is end of file
482: 		{
483: 			bytes -= part;
484: 			got   += part;
485: 		} else if(errno != EINTR && errno != EAGAIN
486: #if defined(EWOULDBLOCK) && (EWOULDBLOCK != EAGAIN)
487: 			&& errno != EWOULDBLOCK
488: #endif
489: 		)
490: 			break;
491: 	}
492: 	return got;
493: }
494: 
495: // and again for streams
496: size_t INT123_unintr_fwrite(const void *ptr, size_t size, size_t nmemb, FILE *stream)
497: {
498: 	size_t written = 0;
499: 	errno = 0;
500: 	while(size && nmemb)
501: 	{
502: 		errno = 0;
503: 		size_t part = fwrite((char*)ptr+written*size, size, nmemb, stream);
504: 		if(part > 0)
505: 		{
506: 			nmemb   -= part;
507: 			written += part;
508: 		} else if(errno != EINTR)
509: 			break;
510: 	}
511: 	return written;
512: }
